@with_appcontext
def routes_command(sort: str, all_methods: bool) -> None:
    """Show all registered routes with endpoints and methods."""

    rules = list(current_app.url_map.iter_rules())
    if not rules:
        click.echo("No routes were registered.")
        return

    ignored_methods = set(() if all_methods else ("HEAD", "OPTIONS"))

    if sort in ("endpoint", "rule"):
        rules = sorted(rules, key=attrgetter(sort))
    elif sort == "methods":
        rules = sorted(rules, key=lambda rule: sorted(rule.methods))  # type: ignore

    rule_methods = [
        ", ".join(sorted(rule.methods - ignored_methods))  # type: ignore
        for rule in rules
    ]

    headers = ["Endpoint", "Methods", "Rule"]
    if current_app.config["SERVER_NAME"]:
        headers.insert(0, "Domain")

    data = []

    for rule, methods in zip(rules, rule_methods):
        if current_app.config["SERVER_NAME"]:
            host = current_app.url_map.bind("localhost").get_host(rule.subdomain)
            hostname = current_app.config["SERVER_NAME"]
            if rule.subdomain and not hostname.startswith(rule.subdomain + "."):
                hostname = f"{rule.subdomain}.{hostname}"
            data.append((hostname, rule.endpoint, methods, rule.rule))
        else:
            data.append((rule.endpoint, methods, rule.rule))

    widths = [max(len(h), *(len(row[i]) for row in data)) for i, h in enumerate(headers)]
    row = "  ".join(f"{{:<{width}}}" for width in widths)

    click.echo(row.format(*headers).strip())
    click.echo(row.format(*(("-" * width for width in widths))))

    for line in data:
        click.echo(row.format(*line).rstrip())


